<?php $pageTitle='Inventory';require_once __DIR__.'/../includes/header.php';require_once __DIR__.'/../includes/sidebar.php';requireRole(['owner','manager']);$db=getDB();$club=$_SESSION['club_id'];if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$id=filter_var($_POST['inventory_item_id']??0,FILTER_VALIDATE_INT);$qty=filter_var($_POST['quantity']??'',FILTER_VALIDATE_FLOAT);if($id&&$qty!==false&&$qty>0){$db->prepare('UPDATE inventory_items SET current_stock=current_stock+? WHERE id=? AND club_id=?')->execute([$qty,$id,$club]);$db->prepare("INSERT INTO inventory_log(inventory_item_id,change_quantity,change_type,vendor_name,cost,created_by) VALUES(?,?, 'purchase',?,?,?)")->execute([$id,$qty,sanitize($_POST['vendor_name']??''),(float)($_POST['cost']??0),$_SESSION['user_id']]);$flash='Stock added.';}}$q=$db->prepare('SELECT * FROM inventory_items WHERE club_id=? ORDER BY category,name');$q->execute([$club]);$items=$q->fetchAll();?><h1 class="text-2xl font-bold">Inventory</h1><p class="text-slate-400 text-sm mt-1">Café stock and club equipment.</p><?php if(isset($flash)):?><p class="text-green-300 mt-4"><?=$flash?></p><?php endif?><section class="card mt-5 overflow-x-auto"><table class="data-table w-full"><thead><tr><th>Name</th><th>Category</th><th>Stock</th><th>Threshold</th><th>Value</th><th>Status</th><th>Add Stock</th></tr></thead><tbody><?php foreach($items as $i):$low=$i['current_stock']<=$i['low_stock_threshold'];?><tr><td class="font-semibold"><?=sanitize($i['name'])?></td><td><?=sanitize($i['category'])?></td><td><?=$i['current_stock']?> <?=sanitize($i['unit'])?></td><td><?=$i['low_stock_threshold']?></td><td><?=money($i['current_stock']*$i['cost_per_unit'])?></td><td class="<?=$low?'text-amber-300':'text-green-400'?>"><?=$low?'LOW':'OK'?></td><td><form method="post" class="flex gap-2"><input type="hidden" name="csrf_token" value="<?=csrfToken()?>"><input type="hidden" name="inventory_item_id" value="<?=$i['id']?>"><input class="input w-20" type="number" name="quantity" min="1" placeholder="Qty"><button class="btn-secondary">Add</button></form></td></tr><?php endforeach?></tbody></table></section><?php require __DIR__.'/../includes/footer.php'; ?>
